-- Spell teacher function
function TraineR._Spells(pPlayer, Class, Team)
	if(TraineR[Class] ~= nil) then
		for i = 1, #TraineR[Class] do
			pPlayer:LearnSpell(TraineR[Class][i])
		end
	end
	if(TraineR[Class..", "..Team] ~= nil) then
		for i = 1, #TraineR[Class..", "..Team] do
			pPlayer:LearnSpell(TraineR[Class..", "..Team][i])
		end
	end
end


