function TraineR._Talents(pPlayer)
	for i = 1, #TraineR.Talents do
		if(TraineR.Talents[i] ~= nil) then
			for l = 2, #TraineR.Talents[i] do
				if(pPlayer:HasSpell(TraineR.Talents[i][1])) then -- HasSpell coming up in a release, not working yet.
					pPlayer:LearnSpell(TraineR.Talents[i][l])
				end
			end
		end
	end
end

