		pPlayer:LearnSpell(TraineR.Mounts[1][i])
	end
	pPlayer:AddSkill(762, 300, 300)
	if(pPlayer:GetTeam() == 0) then
		for i = 1, #TraineR.Mounts[2] do -- train for ally
			pPlayer:LearnSpell(TraineR.Mounts[2][i])
		end
	else
		for i = 1, #TraineR.Mounts[3] do -- train for horde
			pPlayer:LearnSpell(TraineR.Mounts[3][i])
		end
	end
end

function Custom_Trainer_onHeLlO(pUnit, event, pPlayer)

	pUnit:GossipCreateMenu(TEXT_ID, pPlayer, 0)
	pUnit:GossipMenuAddItem(3, "Train all mounts", 1, 0, "", MOUNTCOST)
	pUnit:GossipMenuAddItem(3, "Train all class spells", 2, 0, "", SPELLCOST)
	pUnit:GossipMenuAddItem(3, "Train talent spell ranks", 3, 0, "", TALENTCOST)
	pUnit:GossipMenuAddItem(3, "Reset talents", 4, 0, "", RESETTALENTCOST)
	pUnit:GossipSendMenu(pPlayer)

end

function Custom_Trainer_onSeLeCt(pUnit, event, pPlayer, id, intid, code)

	if(intid == 1) then
		TraineR._Mounts(pPlayer)
		pPlayer:DealGoldCost(MOUNTCOST)
	elseif(intid == 2) then
		TraineR._Spells(pPlayer, pPlayer:GetPlayerClass(), pPlayer:GetTeam())
		pPlayer:DealGoldCost(SPELLCOST)
	elseif(intid == 3) then
		TraineR._Talents(pPlayer)
		pPlayer:DealGoldCost(TALENTCOST)
	elseif(intid == 4) then
		pPlayer:ResetAllTalents()
		pPlayer:DealGoldCost(RESETTALENTCOST)
	end
	Custom_Trainer_onHeLlO(pUnit, event, pPlayer)

end

WorldDBQuery("UPDATE creature_proto SET npcflags = npcflags|1 WHERE entry = "..NPCID)
RegisterUnitGossipEvent(NPCID, 1, Custom_Trainer_onHeLlO)
RegisterUnitGossipEvent(NPCID, 2, Custom_Trainer_onSeLeCt)
